using Microsoft.Data.SqlClient;
using System.Security.Claims;

public static class AdvancedFeatures
{
    static Guid UserId(ClaimsPrincipal user) => Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!);
    static string Role(ClaimsPrincipal user) => user.FindFirstValue(ClaimTypes.Role) ?? "";
    static bool IsManager(ClaimsPrincipal user) => new[]{"owner","manager"}.Contains(Role(user));

    public static void MapAdvancedFeatures(this WebApplication app,string db)
    {
        app.MapGet("/api/toppings",async (Guid? productId)=>{await using var c=new SqlConnection(db);await c.OpenAsync();var sql="SELECT Id,ProductId,Name,Price,IsActive FROM dbo.ProductToppings WHERE IsActive=1"+(productId.HasValue?" AND ProductId=@p":"")+" ORDER BY Name";await using var q=new SqlCommand(sql,c);if(productId.HasValue)q.Parameters.AddWithValue("@p",productId.Value);await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),productId=r.GetGuid(1),name=r.GetString(2),price=r.GetInt32(3),isActive=r.GetBoolean(4)});return Results.Ok(rows);});
        app.MapPost("/api/toppings",async (ToppingInput x,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Chỉ quản lý được thêm topping."},statusCode:403);if(string.IsNullOrWhiteSpace(x.Name)||x.Price<0)return Results.BadRequest(new{error="Topping không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.ProductToppings(ProductId,Name,Price) OUTPUT INSERTED.Id VALUES(@p,@n,@v)",c);q.Parameters.AddWithValue("@p",x.ProductId);q.Parameters.AddWithValue("@n",x.Name.Trim());q.Parameters.AddWithValue("@v",x.Price);try{return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});}catch(SqlException){return Results.Conflict(new{error="Topping đã tồn tại cho món này."});}});
        app.MapDelete("/api/toppings/{id:guid}",async (Guid id,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Không có quyền."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("UPDATE dbo.ProductToppings SET IsActive=0 WHERE Id=@id",c);q.Parameters.AddWithValue("@id",id);return await q.ExecuteNonQueryAsync()>0?Results.NoContent():Results.NotFound();});

        app.MapPatch("/api/tables/{id:guid}/position",async (Guid id,TablePositionInput x,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Chỉ quản lý được sửa sơ đồ bàn."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("UPDATE dbo.DiningTables SET PositionX=@x,PositionY=@y WHERE Id=@id",c);q.Parameters.AddWithValue("@x",x.X);q.Parameters.AddWithValue("@y",x.Y);q.Parameters.AddWithValue("@id",id);return await q.ExecuteNonQueryAsync()>0?Results.Ok(new{id,x=x.X,y=x.Y}):Results.NotFound();});
        app.MapGet("/api/areas",async ()=>{await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("SELECT a.Id,a.Name,a.Position,a.CanvasWidth,a.CanvasHeight,COUNT(t.Id) FROM dbo.Areas a LEFT JOIN dbo.DiningTables t ON t.AreaId=a.Id GROUP BY a.Id,a.Name,a.Position,a.CanvasWidth,a.CanvasHeight ORDER BY a.Position,a.Name",c);await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),name=r.GetString(1),position=r.GetInt32(2),canvasWidth=r.GetInt32(3),canvasHeight=r.GetInt32(4),tableCount=r.GetInt32(5)});return Results.Ok(rows);});
        app.MapPost("/api/areas",async (AreaInput x,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Chỉ quản lý được thêm khu vực."},statusCode:403);if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Tên khu vực không được để trống."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);INSERT dbo.Areas(StoreId,Name,Position,CanvasWidth,CanvasHeight)OUTPUT INSERTED.Id VALUES(@s,@name,(SELECT ISNULL(MAX(Position),0)+1 FROM dbo.Areas),@width,@height)",c);q.Parameters.AddWithValue("@name",x.Name.Trim());q.Parameters.AddWithValue("@width",Math.Clamp(x.CanvasWidth,500,2400));q.Parameters.AddWithValue("@height",Math.Clamp(x.CanvasHeight,400,1600));return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapPatch("/api/areas/{id:guid}",async (Guid id,AreaInput x,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Chỉ quản lý được sửa khu vực."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("UPDATE dbo.Areas SET Name=@name,CanvasWidth=@width,CanvasHeight=@height WHERE Id=@id",c);q.Parameters.AddWithValue("@id",id);q.Parameters.AddWithValue("@name",x.Name.Trim());q.Parameters.AddWithValue("@width",Math.Clamp(x.CanvasWidth,500,2400));q.Parameters.AddWithValue("@height",Math.Clamp(x.CanvasHeight,400,1600));return await q.ExecuteNonQueryAsync()>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapDelete("/api/areas/{id:guid}",async (Guid id,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Chỉ quản lý được xóa khu vực."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("IF EXISTS(SELECT 1 FROM dbo.DiningTables WHERE AreaId=@id) THROW 50003,N'Hãy chuyển hoặc xóa hết bàn trong khu vực trước.',1;IF (SELECT COUNT(*) FROM dbo.Areas)<=1 THROW 50004,N'Quán phải còn ít nhất một khu vực.',1;DELETE dbo.Areas WHERE Id=@id",c);q.Parameters.AddWithValue("@id",id);try{return await q.ExecuteNonQueryAsync()>0?Results.NoContent():Results.NotFound();}catch(SqlException e){return Results.Conflict(new{error=e.Message});}});
        app.MapPatch("/api/tables/{id:guid}/layout",async (Guid id,TableLayoutInput x,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Chỉ quản lý được sửa sơ đồ bàn."},statusCode:403);var shapes=new[]{"rectangle","round","square"};if(!shapes.Contains(x.Shape))return Results.BadRequest(new{error="Kiểu bàn không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("UPDATE dbo.DiningTables SET AreaId=@area,PositionX=@x,PositionY=@y,Width=@width,Height=@height,Shape=@shape WHERE Id=@id",c);q.Parameters.AddWithValue("@id",id);q.Parameters.AddWithValue("@area",x.AreaId);q.Parameters.AddWithValue("@x",Math.Max(0,x.X));q.Parameters.AddWithValue("@y",Math.Max(0,x.Y));q.Parameters.AddWithValue("@width",Math.Clamp(x.Width,90,360));q.Parameters.AddWithValue("@height",Math.Clamp(x.Height,80,260));q.Parameters.AddWithValue("@shape",x.Shape);return await q.ExecuteNonQueryAsync()>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapPost("/api/tables/transfer",async (TableTransferInput x,ClaimsPrincipal user)=>{if(!new[]{"owner","manager","server"}.Contains(Role(user)))return Results.Json(new{error="Không có quyền đổi bàn."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();await using var f=new SqlCommand("SELECT TableId FROM dbo.Orders WHERE Id=@o AND Status NOT IN ('paid','cancelled');SELECT TOP 1 Id FROM dbo.Orders WHERE TableId=@t AND Status NOT IN ('paid','cancelled') ORDER BY OpenedAt DESC",c,(SqlTransaction)tx);f.Parameters.AddWithValue("@o",x.OrderId);f.Parameters.AddWithValue("@t",x.TargetTableId);await using var r=await f.ExecuteReaderAsync();if(!await r.ReadAsync()){await tx.RollbackAsync();return Results.NotFound(new{error="Đơn nguồn không tồn tại."});}var source=r.GetGuid(0);await r.NextResultAsync();Guid? target=await r.ReadAsync()?r.GetGuid(0):null;await r.CloseAsync();if(target.HasValue&&!x.Merge){await tx.RollbackAsync();return Results.Conflict(new{error="Bàn đích đang có khách. Hãy chọn gộp bàn."});}if(target.HasValue){await using var q=new SqlCommand("UPDATE dbo.OrderItems SET OrderId=@target WHERE OrderId=@sourceOrder;UPDATE dbo.Orders SET Subtotal=Subtotal+(SELECT Subtotal FROM dbo.Orders WHERE Id=@sourceOrder),Total=Total+(SELECT Total FROM dbo.Orders WHERE Id=@sourceOrder),Status='sent' WHERE Id=@target;UPDATE dbo.Orders SET Status='cancelled',ClosedAt=SYSUTCDATETIME(),Note=CONCAT(ISNULL(Note,''),N' [Đã gộp vào đơn khác]') WHERE Id=@sourceOrder",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@target",target.Value);q.Parameters.AddWithValue("@sourceOrder",x.OrderId);await q.ExecuteNonQueryAsync();}else{await using var q=new SqlCommand("UPDATE dbo.Orders SET TableId=@target WHERE Id=@order",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@target",x.TargetTableId);q.Parameters.AddWithValue("@order",x.OrderId);await q.ExecuteNonQueryAsync();}await using(var q=new SqlCommand("UPDATE dbo.DiningTables SET Status='available' WHERE Id=@source;UPDATE dbo.DiningTables SET Status='occupied' WHERE Id=@target",c,(SqlTransaction)tx)){q.Parameters.AddWithValue("@source",source);q.Parameters.AddWithValue("@target",x.TargetTableId);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();return Results.Ok(new{orderId=target??x.OrderId,targetTableId=x.TargetTableId,merged=target.HasValue});});

        app.MapGet("/api/customers",async (string? phone)=>{await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("SELECT TOP 30 Id,FullName,Phone,Points,TotalSpent,CreatedAt FROM dbo.Customers WHERE @phone='' OR Phone LIKE @phone+'%' ORDER BY TotalSpent DESC",c);q.Parameters.AddWithValue("@phone",phone?.Trim()??"");await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),name=r.GetString(1),phone=r.GetString(2),points=r.GetInt32(3),totalSpent=r.GetInt64(4),createdAt=r.GetDateTime(5)});return Results.Ok(rows);});
        app.MapPost("/api/customers",async (CustomerInput x)=>{if(string.IsNullOrWhiteSpace(x.Phone)||string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Nhập tên và số điện thoại."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);MERGE dbo.Customers t USING(SELECT @s StoreId,@phone Phone)s ON t.StoreId=s.StoreId AND t.Phone=s.Phone WHEN MATCHED THEN UPDATE SET FullName=@name WHEN NOT MATCHED THEN INSERT(StoreId,Phone,FullName)VALUES(@s,@phone,@name) OUTPUT inserted.Id,inserted.FullName,inserted.Phone,inserted.Points;",c);q.Parameters.AddWithValue("@phone",x.Phone.Trim());q.Parameters.AddWithValue("@name",x.Name.Trim());await using var r=await q.ExecuteReaderAsync();await r.ReadAsync();return Results.Ok(new{id=r.GetGuid(0),name=r.GetString(1),phone=r.GetString(2),points=r.GetInt32(3)});});
        app.MapPost("/api/orders/{id:guid}/customer",async (Guid id,OrderCustomerInput x)=>{await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("UPDATE dbo.Orders SET CustomerId=@customer WHERE Id=@id AND Status NOT IN ('paid','cancelled')",c);q.Parameters.AddWithValue("@customer",x.CustomerId);q.Parameters.AddWithValue("@id",id);return await q.ExecuteNonQueryAsync()>0?Results.Ok(new{id,customerId=x.CustomerId}):Results.NotFound();});
        app.MapPost("/api/orders/{id:guid}/redeem-points",async (Guid id,RedeemPointsInput x)=>{if(x.Points<=0)return Results.BadRequest(new{error="Số điểm phải lớn hơn 0."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();await using var q=new SqlCommand("SELECT o.CustomerId,o.Subtotal,o.Discount,o.PointsRedeemed,c.Points FROM dbo.Orders o LEFT JOIN dbo.Customers c ON c.Id=o.CustomerId WHERE o.Id=@id AND o.Status NOT IN ('paid','cancelled')",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@id",id);await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync()||r.IsDBNull(0)){await tx.RollbackAsync();return Results.BadRequest(new{error="Hãy gắn khách hàng vào đơn trước."});}var customer=r.GetGuid(0);var subtotal=r.GetInt32(1);var promotionDiscount=r.GetInt32(2);var already=r.GetInt32(3);var balance=r.GetInt32(4);await r.CloseAsync();if(already>0){await tx.RollbackAsync();return Results.Conflict(new{error="Đơn này đã đổi điểm."});}var points=Math.Min(x.Points,balance);var discount=Math.Min(points*1000,Math.Max(0,subtotal-promotionDiscount));points=discount/1000;if(points<=0){await tx.RollbackAsync();return Results.BadRequest(new{error="Đơn không còn giá trị để đổi điểm."});}await using var u=new SqlCommand("UPDATE dbo.Customers SET Points=Points-@points WHERE Id=@customer;UPDATE dbo.Orders SET PointsRedeemed=@points,LoyaltyDiscount=@discount,Total=Subtotal-Discount-@discount WHERE Id=@id",c,(SqlTransaction)tx);u.Parameters.AddWithValue("@points",points);u.Parameters.AddWithValue("@discount",discount);u.Parameters.AddWithValue("@customer",customer);u.Parameters.AddWithValue("@id",id);await u.ExecuteNonQueryAsync();await tx.CommitAsync();return Results.Ok(new{points,discount,total=subtotal-promotionDiscount-discount});});

        app.MapGet("/api/promotions",async ()=>{await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("SELECT Id,Code,Name,DiscountType,Value,MinimumOrder,MaximumDiscount,StartsAt,EndsAt,IsActive FROM dbo.Promotions ORDER BY CreatedAt DESC",c);await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),code=r.GetString(1),name=r.GetString(2),type=r.GetString(3),value=r.GetInt32(4),minimumOrder=r.GetInt32(5),maximumDiscount=r.IsDBNull(6)?(int?)null:r.GetInt32(6),startsAt=r.IsDBNull(7)?(DateTime?)null:r.GetDateTime(7),endsAt=r.IsDBNull(8)?(DateTime?)null:r.GetDateTime(8),isActive=r.GetBoolean(9)});return Results.Ok(rows);});
        app.MapPost("/api/promotions",async (PromotionInput x,ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Không có quyền tạo khuyến mãi."},statusCode:403);if(!new[]{"percent","fixed"}.Contains(x.Type)||x.Value<=0)return Results.BadRequest(new{error="Khuyến mãi không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);INSERT dbo.Promotions(StoreId,Code,Name,DiscountType,Value,MinimumOrder,MaximumDiscount,StartsAt,EndsAt) OUTPUT INSERTED.Id VALUES(@s,@code,@name,@type,@value,@min,@max,@start,@end)",c);q.Parameters.AddWithValue("@code",x.Code.Trim().ToUpperInvariant());q.Parameters.AddWithValue("@name",x.Name.Trim());q.Parameters.AddWithValue("@type",x.Type);q.Parameters.AddWithValue("@value",x.Value);q.Parameters.AddWithValue("@min",x.MinimumOrder);q.Parameters.AddWithValue("@max",(object?)x.MaximumDiscount??DBNull.Value);q.Parameters.AddWithValue("@start",(object?)x.StartsAt??DBNull.Value);q.Parameters.AddWithValue("@end",(object?)x.EndsAt??DBNull.Value);try{return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});}catch(SqlException){return Results.Conflict(new{error="Mã khuyến mãi đã tồn tại."});}});
        app.MapPost("/api/orders/{id:guid}/promotion",async (Guid id,ApplyPromotionInput x)=>{await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();await using var q=new SqlCommand("SELECT TOP 1 Id,DiscountType,Value,MinimumOrder,MaximumDiscount FROM dbo.Promotions WHERE Code=@code AND IsActive=1 AND (StartsAt IS NULL OR StartsAt<=SYSUTCDATETIME()) AND (EndsAt IS NULL OR EndsAt>=SYSUTCDATETIME());SELECT Subtotal,LoyaltyDiscount FROM dbo.Orders WHERE Id=@id AND Status NOT IN ('paid','cancelled')",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@code",x.Code.Trim().ToUpperInvariant());q.Parameters.AddWithValue("@id",id);await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync()){await tx.RollbackAsync();return Results.NotFound(new{error="Mã giảm giá không hợp lệ hoặc đã hết hạn."});}var promotion=r.GetGuid(0);var type=r.GetString(1);var value=r.GetInt32(2);var minimum=r.GetInt32(3);var maximum=r.IsDBNull(4)?(int?)null:r.GetInt32(4);await r.NextResultAsync();if(!await r.ReadAsync()){await tx.RollbackAsync();return Results.NotFound(new{error="Không tìm thấy đơn."});}var subtotal=r.GetInt32(0);var loyalty=r.GetInt32(1);await r.CloseAsync();if(subtotal<minimum){await tx.RollbackAsync();return Results.BadRequest(new{error=$"Đơn tối thiểu {minimum:N0}đ."});}var discount=type=="percent"?subtotal*value/100:value;if(maximum.HasValue)discount=Math.Min(discount,maximum.Value);discount=Math.Min(discount,subtotal-loyalty);await using var u=new SqlCommand("UPDATE dbo.Orders SET PromotionId=@p,Discount=@d,Total=Subtotal-@d-LoyaltyDiscount WHERE Id=@id",c,(SqlTransaction)tx);u.Parameters.AddWithValue("@p",promotion);u.Parameters.AddWithValue("@d",discount);u.Parameters.AddWithValue("@id",id);await u.ExecuteNonQueryAsync();await tx.CommitAsync();return Results.Ok(new{id,discount,total=subtotal-discount-loyalty});});

        app.MapGet("/api/shifts/current",async (ClaimsPrincipal user)=>
        {
            await using var c=new SqlConnection(db);await c.OpenAsync();
            await using var q=new SqlCommand(@"SELECT TOP 1 s.Id,s.OpenedAt,s.OpeningCash,s.Status,
ISNULL(x.CashSales,0),ISNULL(x.NonCashSales,0),ISNULL(x.TotalSales,0),ISNULL(x.TransactionCount,0),s.OpeningCash+ISNULL(x.CashSales,0)
FROM dbo.WorkShifts s OUTER APPLY(
 SELECT SUM(CASE WHEN p.Method='cash' THEN p.Amount ELSE 0 END) CashSales,
        SUM(CASE WHEN p.Method<>'cash' THEN p.Amount ELSE 0 END) NonCashSales,
        SUM(p.Amount) TotalSales,COUNT(*) TransactionCount
 FROM dbo.Payments p WHERE p.ReceivedBy=s.OpenedBy AND p.PaidAt>=s.OpenedAt AND p.PaidAt<=SYSUTCDATETIME()
)x WHERE s.OpenedBy=@u AND s.Status='open' ORDER BY s.OpenedAt DESC",c);
            q.Parameters.AddWithValue("@u",UserId(user));await using var r=await q.ExecuteReaderAsync();
            return await r.ReadAsync()?Results.Ok(new{id=r.GetGuid(0),openedAt=r.GetDateTime(1),openingCash=r.GetInt32(2),status=r.GetString(3),cashSales=r.GetInt32(4),nonCashSales=r.GetInt32(5),totalSales=r.GetInt32(6),transactionCount=r.GetInt32(7),expectedCash=r.GetInt32(8)}):Results.Ok((object?)null);
        });
        app.MapPost("/api/shifts/open",async (OpenShiftInput x,ClaimsPrincipal user)=>{if(!new[]{"owner","manager","cashier"}.Contains(Role(user)))return Results.Json(new{error="Không có quyền mở ca."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();var uid=UserId(user);await using var q=new SqlCommand("IF EXISTS(SELECT 1 FROM dbo.WorkShifts WHERE OpenedBy=@u AND Status='open') THROW 50001,N'Bạn đang có một ca chưa kết thúc.',1;DECLARE @s uniqueidentifier=(SELECT TOP 1 Id FROM dbo.Stores);INSERT dbo.WorkShifts(StoreId,OpenedBy,OpeningCash) OUTPUT INSERTED.Id,INSERTED.OpenedAt VALUES(@s,@u,@cash)",c);q.Parameters.AddWithValue("@u",uid);q.Parameters.AddWithValue("@cash",x.OpeningCash);try{await using var r=await q.ExecuteReaderAsync();await r.ReadAsync();return Results.Ok(new{id=r.GetGuid(0),openedAt=r.GetDateTime(1)});}catch(SqlException e){return Results.Conflict(new{error=e.Message});}});
        app.MapPost("/api/shifts/{id:guid}/close",async (Guid id,CloseShiftInput x,ClaimsPrincipal user)=>
        {
            if(!new[]{"owner","manager","cashier"}.Contains(Role(user)))return Results.Json(new{error="Không có quyền kết ca."},statusCode:403);
            await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand(@"DECLARE @closedAt datetime2=SYSUTCDATETIME(),@openedAt datetime2,@openedBy uniqueidentifier,@opening int;
SELECT @openedAt=OpenedAt,@openedBy=OpenedBy,@opening=OpeningCash FROM dbo.WorkShifts WHERE Id=@id AND Status='open';
DECLARE @cashSales int=ISNULL((SELECT SUM(Amount) FROM dbo.Payments WHERE ReceivedBy=@openedBy AND Method='cash' AND PaidAt>=@openedAt AND PaidAt<=@closedAt),0);
DECLARE @nonCashSales int=ISNULL((SELECT SUM(Amount) FROM dbo.Payments WHERE ReceivedBy=@openedBy AND Method<>'cash' AND PaidAt>=@openedAt AND PaidAt<=@closedAt),0);
DECLARE @transactions int=ISNULL((SELECT COUNT(*) FROM dbo.Payments WHERE ReceivedBy=@openedBy AND PaidAt>=@openedAt AND PaidAt<=@closedAt),0);
DECLARE @expected int=@opening+@cashSales;
UPDATE dbo.WorkShifts SET Status='closed',ClosedBy=@u,ClosedAt=@closedAt,ClosingCash=@cash,ExpectedCash=@expected,Variance=@cash-@expected,Note=@note
OUTPUT INSERTED.ExpectedCash,INSERTED.Variance,@cashSales,@nonCashSales,@cashSales+@nonCashSales,@transactions WHERE Id=@id AND Status='open';",c);
            q.Parameters.AddWithValue("@id",id);q.Parameters.AddWithValue("@u",UserId(user));q.Parameters.AddWithValue("@cash",x.ClosingCash);q.Parameters.AddWithValue("@note",(object?)x.Note??DBNull.Value);await using var r=await q.ExecuteReaderAsync();
            return await r.ReadAsync()?Results.Ok(new{expectedCash=r.GetInt32(0),variance=r.GetInt32(1),cashSales=r.GetInt32(2),nonCashSales=r.GetInt32(3),totalSales=r.GetInt32(4),transactionCount=r.GetInt32(5)}):Results.NotFound(new{error="Ca không tồn tại hoặc đã đóng."});
        });
        app.MapGet("/api/shifts",async (ClaimsPrincipal user)=>
        {
            if(!new[]{"owner","manager","cashier"}.Contains(Role(user)))return Results.Json(new{error="Không có quyền xem lịch sử ca."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();var filter=Role(user)=="cashier"?" WHERE s.OpenedBy=@user":"";
            await using var q=new SqlCommand(@"SELECT TOP 100 s.Id,u.FullName,s.OpenedAt,s.ClosedAt,s.OpeningCash,s.ClosingCash,s.ExpectedCash,s.Variance,s.Status,
ISNULL(x.CashSales,0),ISNULL(x.NonCashSales,0),ISNULL(x.TotalSales,0),ISNULL(x.TransactionCount,0)
FROM dbo.WorkShifts s JOIN dbo.Users u ON u.Id=s.OpenedBy OUTER APPLY(
 SELECT SUM(CASE WHEN p.Method='cash' THEN p.Amount ELSE 0 END) CashSales,
        SUM(CASE WHEN p.Method<>'cash' THEN p.Amount ELSE 0 END) NonCashSales,
        SUM(p.Amount) TotalSales,COUNT(*) TransactionCount
 FROM dbo.Payments p WHERE p.ReceivedBy=s.OpenedBy AND p.PaidAt>=s.OpenedAt AND p.PaidAt<=COALESCE(s.ClosedAt,SYSUTCDATETIME())
)x"+filter+" ORDER BY s.OpenedAt DESC",c);
            q.Parameters.AddWithValue("@user",UserId(user));await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();
            while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),staff=r.GetString(1),openedAt=r.GetDateTime(2),closedAt=r.IsDBNull(3)?(DateTime?)null:r.GetDateTime(3),openingCash=r.GetInt32(4),closingCash=r.IsDBNull(5)?(int?)null:r.GetInt32(5),expectedCash=r.IsDBNull(6)?(int?)null:r.GetInt32(6),variance=r.IsDBNull(7)?(int?)null:r.GetInt32(7),status=r.GetString(8),cashSales=r.GetInt32(9),nonCashSales=r.GetInt32(10),totalSales=r.GetInt32(11),transactionCount=r.GetInt32(12)});return Results.Ok(rows);
        });

        app.MapGet("/api/reports/operations",async (ClaimsPrincipal user)=>{if(!IsManager(user))return Results.Json(new{error="Không có quyền xem báo cáo vận hành."},statusCode:403);await using var c=new SqlConnection(db);await c.OpenAsync();var result=new Dictionary<string,object>();await using(var q=new SqlCommand("SELECT TOP 100 c.CreatedAt,o.OrderNumber,ISNULL(i.ProductName,N'Toàn đơn'),c.Reason,c.Amount,ISNULL(u.FullName,N'Hệ thống') FROM dbo.OrderCancellations c JOIN dbo.Orders o ON o.Id=c.OrderId LEFT JOIN dbo.OrderItems i ON i.Id=c.OrderItemId LEFT JOIN dbo.Users u ON u.Id=c.CancelledBy ORDER BY c.CreatedAt DESC",c)){await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{createdAt=r.GetDateTime(0),orderNumber=r.GetInt64(1),item=r.GetString(2),reason=r.GetString(3),amount=r.GetInt32(4),staff=r.GetString(5)});result["cancellations"]=rows;}await using(var q=new SqlCommand("SELECT u.Id,u.FullName,u.Role,COUNT(DISTINCT o.Id),COUNT(DISTINCT CASE WHEN i.PreparedBy=u.Id THEN i.Id END),ISNULL(SUM(CASE WHEN p.ReceivedBy=u.Id THEN p.Amount ELSE 0 END),0) FROM dbo.Users u LEFT JOIN dbo.Orders o ON o.OpenedBy=u.Id LEFT JOIN dbo.OrderItems i ON i.OrderId=o.Id LEFT JOIN dbo.Payments p ON p.OrderId=o.Id WHERE u.IsActive=1 GROUP BY u.Id,u.FullName,u.Role ORDER BY u.FullName",c)){await using var r=await q.ExecuteReaderAsync();var rows=new List<object>();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),name=r.GetString(1),role=r.GetString(2),orders=r.GetInt32(3),preparedItems=r.GetInt32(4),receivedAmount=r.GetInt32(5)});result["staffPerformance"]=rows;}return Results.Ok(result);});
    }
}

